```python
from cirq.contrib.qasm_import import circuit_from_qasm

qasm = """
OPENQASM 2.0;
include "qelib1.inc";

qreg q[3];
creg m_c0[1];
creg m_c1[1];
creg m_c2[1];

h q[0];
h q[1];
x q[2];
cx q[0],q[1];
h q[0];
if(m_c2==1) cx q[1],q[0];
if(m_c2==1) id q[2];
measure q[0] -> m_c0[0];
measure q[1] -> m_c1[0];
measure q[2] -> m_c2[0];
"""

circuit = circuit_from_qasm(qasm)
print(circuit)
